Lub `xf_role_info`.id` in ( '123430'));
Wybierz count(*) z `xf_function_info`;
Wybierz 1 z `config_default_values`;
Wybierz count(distinct id) z `XF_EVENT` (gdzie `event_time` jest między '11:51:07' a '12:03:06');
count(`name`) + sum(`pages`) + sum(case when status = 0 then 1 else -1 end) `pages`.
